<template>
  <DatePicker
    v-model:open="isOpen"
    :model-value="startDateLocal"
    :placeholder="placeholder"
    :icon="icon"
    @update:model-value="onChange"
  />
</template>
<script setup lang="ts">
import type { CalendarDate } from '@internationalized/date';

interface Props {
  label?: string;
  value: string | null;
  placeholder?: string;
  propertyName: string;
  icon?: any;
}
const props = defineProps<Props>();
const route = useRoute();
const isOpen = ref<boolean>(false);

const startDateLocal = computed<CalendarDate | null>(() => {
  return props.value ? processStartDateProps(props.value) || null : null;
});

async function onChange(value: CalendarDate | null) {
  isOpen.value = false;
  await navigateTo({
    name: route.name,
    params: route.params,
    query: {
      ...route.query,
      page: 1,
      [props.propertyName]: value ? value.toString() : undefined,
    },
  });
}
</script>
